import Foundation

/// ICC profiles generated by the app (docs/decisions.md: output profiles are
/// generated or taken from ColorSync at run time, never committed as files).
public enum ICCProfiles {
    /// ICC v4 grey display profile with the sRGB tone curve (parametric curve
    /// type 3) and a D50 white point, for 8-bit grey exports. Built here
    /// because ColorSync has no named grey profile with the sRGB curve.
    public static let graySRGB: Data = makeGraySRGB()

    private static func makeGraySRGB() -> Data {
        func be32(_ v: UInt32) -> Data { Data([UInt8(v >> 24), UInt8(truncatingIfNeeded: v >> 16), UInt8(truncatingIfNeeded: v >> 8), UInt8(truncatingIfNeeded: v)]) }
        func be16(_ v: UInt16) -> Data { Data([UInt8(v >> 8), UInt8(truncatingIfNeeded: v)]) }
        func sig(_ s: String) -> Data { Data(s.utf8) }
        func s15(_ v: Double) -> Data { be32(UInt32(bitPattern: Int32((v * 65_536).rounded()))) }
        func padded(_ d: Data) -> Data { d.count % 4 == 0 ? d : d + Data(count: 4 - d.count % 4) }
        func mluc(_ text: String) -> Data {
            let utf16 = text.utf16.flatMap { [UInt8($0 >> 8), UInt8(truncatingIfNeeded: $0)] }
            return sig("mluc") + be32(0) + be32(1) + be32(12) + sig("enUS") + be32(UInt32(utf16.count)) + be32(28) + Data(utf16)
        }
        let d50 = s15(0.9642) + s15(1.0) + s15(0.8249)
        let tags: [(String, Data)] = [
            ("desc", mluc("Gray, sRGB curve (X1 Scan)")),
            ("cprt", mluc("No copyright, use freely")),
            ("wtpt", sig("XYZ ") + be32(0) + d50),
            ("kTRC", sig("para") + be32(0) + be16(3) + be16(0)
                + s15(2.4) + s15(1 / 1.055) + s15(0.055 / 1.055) + s15(1 / 12.92) + s15(0.040_45)),
        ]
        let tableSize = 4 + tags.count * 12
        var offset = 128 + tableSize
        var table = be32(UInt32(tags.count))
        var bodies = Data()
        for (name, body) in tags {
            table += sig(name) + be32(UInt32(offset)) + be32(UInt32(body.count))
            let block = padded(body)
            bodies += block
            offset += block.count
        }
        let size = 128 + tableSize + bodies.count
        var header = be32(UInt32(size)) + be32(0) + be32(0x0430_0000) + sig("mntr") + sig("GRAY") + sig("XYZ ")
        header += be16(2026) + be16(11) + be16(14) + be16(0) + be16(0) + be16(0)  // creation date, fixed
        header += sig("acsp") + be32(0) + be32(0) + be32(0) + be32(0) + be32(0) + be32(0)  // platform, flags, manufacturer, model, attributes (8)
        header += be32(0) + d50 + be32(0)  // perceptual intent, PCS illuminant D50, creator
        header += Data(count: 16 + 28)     // profile ID (not computed) and reserved bytes
        precondition(header.count == 128)
        return header + table + bodies
    }
}
